shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-subtle: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0af;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-text: #eef2f6;
    --navy-muted: #9eb0c2;
    --font-serif-cn: 'Noto Serif SC', serif;
    --font-sans-cn: 'Noto Sans SC', sans-serif;
    --font-serif-en: 'Lora', Georgia, serif;
    --font-display: 'Playfair Display', 'Noto Serif SC', serif;
    --font-ui: 'Inter', 'Noto Sans SC', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  :host([lang="zh-CN"]) .wsj-shadow-body {
    font-family: var(--font-serif-cn);
  }
  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
  }

  /* Progress Bar */
  .reading-progress {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    background: var(--accent);
    width: 0%;
    z-index: 1001;
    transition: width 0.1s ease-out;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--line);
    padding: 0.75rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-cluster {
    display: flex;
    align-items: center;
    gap: 0.85rem;
  }

  .wsj-monogram {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.25rem;
    letter-spacing: 0.04em;
    color: var(--ink);
    text-decoration: none;
  }

  .brand-divider {
    width: 1px;
    height: 16px;
    background: var(--line-strong);
  }

  .section-badge {
    font-family: var(--font-ui);
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
  }

  .lang-toggle {
    display: inline-flex;
    align-items: center;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-ui);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.3rem 0.75rem;
    border-radius: 999px;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.2s ease;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .article-hero {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 1px solid var(--ink);
  }

  .hero-kicker-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  .kicker-pill {
    background: var(--ink);
    color: var(--paper);
    padding: 0.2rem 0.55rem;
    font-weight: 600;
    letter-spacing: 0.08em;
  }

  .article-title {
    font-family: var(--font-display);
    font-weight: 800;
    color: var(--ink);
    line-height: 1.22;
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    max-width: 980px;
    margin-bottom: 1.35rem;
  }

  :host([lang="en"]) .article-title {
    line-height: 1.12;
    letter-spacing: -0.015em;
  }

  .article-dek {
    font-size: clamp(1.08rem, 1.6vw, 1.3rem);
    line-height: 1.68;
    color: var(--muted);
    max-width: 840px;
    margin-bottom: 2rem;
    font-weight: 400;
  }

  .byline-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-ui);
    font-size: 0.85rem;
    color: var(--muted);
  }

  .byline-authors strong {
    color: var(--ink);
    font-weight: 600;
  }

  .byline-meta {
    font-family: var(--font-mono);
    font-size: 0.78rem;
  }

  /* Main Container & Asymmetric Editorial Grid */
  .editorial-container {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.75rem 1.5rem 4.5rem;
  }

  .editorial-chapter {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 340px;
    gap: 3.5rem;
    align-items: start;
    margin-bottom: 3.5rem;
  }

  .prose-column {
    max-width: 680px;
  }

  .rail-column {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Prose Typography */
  .prose-p {
    font-size: 1.125rem;
    line-height: 1.88;
    color: var(--body);
    margin-bottom: 1.55rem;
    letter-spacing: 0.01em;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.14rem;
    line-height: 1.8;
    letter-spacing: 0;
  }

  /* Lead paragraph styling (NO ::first-letter on Chinese) */
  .prose-lead {
    font-size: 1.24rem;
    line-height: 1.82;
    color: var(--ink);
    font-weight: 600;
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.85rem;
  }

  :host([lang="en"]) .prose-lead {
    font-size: 1.25rem;
    line-height: 1.72;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, var(--accent-soft) 58%);
    color: inherit;
    padding: 0 2px;
    font-weight: 600;
    border-bottom: 1px solid rgba(184, 93, 25, 0.45);
  }

  /* Official Response Micro-Callout (for p5) */
  .official-note {
    font-family: var(--font-ui);
    font-size: 0.95rem;
    line-height: 1.6;
    color: var(--muted);
    background: var(--paper-card);
    border-left: 3px solid var(--ink);
    padding: 0.85rem 1.15rem;
    margin: 1.5rem 0 1.75rem;
  }

  /* Split Sentence Climactic Quote Box */
  .stage-quote-box {
    margin: 1.75rem 0 2rem;
    padding: 1.5rem 1.75rem;
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
  }

  .stage-quote-box .prose-p {
    margin-bottom: 0.85rem;
    font-size: 1.05rem;
    color: var(--muted);
  }

  .verdict-quote {
    font-family: var(--font-display);
    font-size: clamp(1.3rem, 2vw, 1.58rem);
    font-weight: 700;
    line-height: 1.45;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1rem;
    margin-top: 0.5rem;
  }

  /* Sidebar Dossier & Derived Quote Cards */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.35rem 1.4rem;
  }

  .dossier-header {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    margin-bottom: 0.45rem;
    font-weight: 700;
  }

  .dossier-title {
    font-family: var(--font-display);
    font-size: 1.08rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.9rem;
    padding-bottom: 0.6rem;
    border-bottom: 1px solid var(--line);
  }

  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
  }

  .dossier-item {
    font-family: var(--font-ui);
    font-size: 0.84rem;
    line-height: 1.55;
    color: var(--body);
  }

  .dossier-item strong {
    display: block;
    color: var(--ink);
    font-weight: 600;
    margin-bottom: 0.15rem;
  }

  .pull-quote {
    background: var(--paper-card);
    border-top: 2px solid var(--accent);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.35rem 1.35rem;
  }

  .pull-quote .quote-text {
    font-family: var(--font-display);
    font-size: 1.08rem;
    font-weight: 700;
    line-height: 1.58;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  /* Bespoke Graphic Interlude (Political Calculus SVG) */
  .graphic-interlude {
    margin: 1rem 0 3.75rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 2rem 1.75rem;
  }

  .graphic-header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--line-strong);
  }

  .graphic-kicker {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 700;
    margin-bottom: 0.35rem;
  }

  .graphic-title {
    font-family: var(--font-display);
    font-size: 1.4rem;
    color: var(--ink);
    font-weight: 800;
  }

  .graphic-sub {
    font-family: var(--font-ui);
    font-size: 0.86rem;
    color: var(--muted);
    max-width: 520px;
  }

  .svg-wrapper {
    width: 100%;
    overflow: hidden;
  }

  .svg-wrapper svg {
    width: 100%;
    height: auto;
    display: block;
  }

  /* Memoir Feature Box (107 Days) */
  .memoir-chapter {
    background: var(--navy-bg);
    color: var(--navy-text);
    padding: 3rem 2.25rem;
    margin-bottom: 3.75rem;
    border-top: 4px solid var(--accent);
  }

  .memoir-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 320px;
    gap: 3rem;
    align-items: start;
  }

  .memoir-kicker {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #e58d4e;
    margin-bottom: 0.5rem;
  }

  .memoir-heading {
    font-family: var(--font-display);
    font-size: 1.65rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 1.5rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.16);
  }

  .memoir-chapter .prose-p {
    color: #e6ecf2;
  }

  .memoir-chapter mark.ed-hl {
    background: rgba(229, 141, 78, 0.22);
    border-bottom-color: #e58d4e;
    color: #ffffff;
  }

  .memoir-chapter .pull-quote {
    background: var(--navy-card);
    border-top: 2px solid #e58d4e;
    border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  }

  .memoir-chapter .pull-quote .quote-text {
    color: #ffffff;
  }

  .memoir-chapter .pull-quote .quote-attrib {
    color: var(--navy-muted);
  }

  .career-timeline {
    background: var(--navy-card);
    border: 1px solid rgba(255, 255, 255, 0.14);
    padding: 1.25rem;
  }

  .career-timeline-title {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #e58d4e;
    margin-bottom: 0.85rem;
  }

  .timeline-step {
    position: relative;
    padding-left: 1rem;
    border-left: 2px solid rgba(229, 141, 78, 0.45);
    margin-bottom: 0.9rem;
    font-family: var(--font-ui);
    font-size: 0.82rem;
    line-height: 1.5;
    color: #dbe3ec;
  }

  .timeline-step:last-child {
    margin-bottom: 0;
  }

  .timeline-step span.year {
    display: block;
    font-family: var(--font-mono);
    font-weight: 700;
    color: #ffffff;
    font-size: 0.76rem;
  }

  /* Final Chapter Closing Quote */
  .closing-coda {
    margin-top: 1.25rem;
    padding: 1.35rem 1.5rem;
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
  }

  .closing-coda .prose-p {
    margin-bottom: 0;
    font-family: var(--font-display);
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--ink);
  }

  /* Footer */
  .editorial-footer {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2rem 1.5rem 4rem;
    border-top: 1px solid var(--line-strong);
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1rem;
    font-family: var(--font-ui);
    font-size: 0.8rem;
    color: var(--muted);
  }

  /* Responsive Design */
  @media (max-width: 960px) {
    .editorial-chapter,
    .memoir-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }

    .prose-column {
      max-width: 100%;
    }
  }

  @media (max-width: 600px) {
    .masthead {
      padding: 0.65rem 1rem;
    }
    .article-hero {
      padding: 2.25rem 1rem 1.75rem;
    }
    .editorial-container {
      padding: 2rem 1rem 3rem;
    }
    .memoir-chapter {
      padding: 2rem 1.15rem;
    }
    .graphic-interlude {
      padding: 1.35rem 1rem;
    }
    .prose-p {
      font-size: 1.06rem;
      line-height: 1.82;
    }
    .prose-lead {
      font-size: 1.14rem;
    }
  }
